<?php
namespace App\Http\Controllers;
use Illuminate\Routing\Controller;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\Auth;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Hash;
use Illuminate\Validation\Rule;
class CommonController extends Controller {
 public function authForm(Request $r){return view('auth',['register'=>$r->is('register'),'roles'=>['sorting_center','rider']]);}
 public function register(Request $r){return app(CompanyRegistrationController::class)->register($r);}
 public function login(Request $r){$r->merge(['email'=>mb_strtolower(trim((string)$r->email))]);$v=$r->validate(['email'=>'required|email','password'=>'required']);if(!Auth::attempt($v))return back()->withErrors(['email'=>'Incorrect login details.']);$r->session()->regenerate();$u=Auth::user();if($u->approval_status==='unverified'&&in_array($u->role,['sorting_center','rider'])){Auth::logout();$r->session()->put('company_pending_registration_id',\App\Services\PendingRegistration::resumeLegacy($u->id));return redirect('/company/verify');}if($u->approval_status!=='approved'||!$u->active||$u->account_status!=='active'){Auth::logout();return back()->withErrors(['email'=>'Account waiting for approval or inactive. '.($u->rejection_reason??'')]);}$roles=['sorting_center','rider','logistics_admin'];if(!in_array($u->role,$roles,true)){Auth::logout();return back()->withErrors(['email'=>'Use the correct LokaShop website for this role.']);}DB::table('users')->where('id',$u->id)->update(['last_seen_at'=>now()]);return redirect('/dashboard');}
 public function logout(Request $r){DB::table('users')->where('id',auth()->id())->update(['online'=>0,'last_seen_at'=>null]);Auth::logout();$r->session()->invalidate();$r->session()->regenerateToken();return redirect('/login');}
 public function dashboard(){if(auth()->user()->role==='logistics_admin')return app(LogisticsWorkspaceController::class)->overview(request());if(auth()->user()->role==='sorting_center')return redirect('/ops/overview');return view('dashboard',['links'=>$this->links()]);}
 public function links(){return match(auth()->user()->role){'buyer'=>['Shop'=>'/','Cart'=>'/cart','My orders'=>'/orders','Addresses'=>'/addresses','Feedback'=>'/ratings','Complaints'=>'/complaints'],'seller'=>['Products'=>'/seller/products','Orders'=>'/seller/orders','Sales'=>'/seller/reports','Feedback'=>'/ratings'],'admin'=>['Approvals'=>'/admin/approvals','Users'=>'/admin/users','Products'=>'/admin/products','Complaints'=>'/complaints','Reports'=>'/admin/reports','Announcements'=>'/admin/announcements'],'logistics_admin'=>['Shipping commission'=>'/admin/commissions','Territories'=>'/ops/territories','Legacy riders'=>'/ops/legacy','Applications'=>'/admin/approvals','Users'=>'/admin/users'],'sorting_center'=>['Rider applications'=>'/center/approvals','Riders and drivers'=>'/ops/riders','Center transfers'=>'/ops/transfers','Shipping rates'=>'/ops/rates','Tracking'=>'/ops/tracking','Returns'=>'/ops/returns','COD'=>'/ops/cod','Pickups'=>'/center/pickups','Delivery'=>'/center/delivery','Parcels'=>'/center/parcels','Areas'=>'/center/areas','Reports'=>'/center/reports'],'rider'=>['Availability'=>'/ops/availability','Vehicle'=>'/ops/vehicle','COD'=>'/ops/cod','Assignments'=>'/rider/assignments','Earnings'=>'/rider/earnings'],default=>[]};}
 public function profile(){return view('profile',['links'=>$this->links(),'user'=>auth()->user(),'notifications'=>DB::table('notifications')->where('user_id',auth()->id())->orderByDesc('id')->limit(20)->get()]);}
 public function updateProfile(Request $r){\App\Services\Cart::profile($r);return back()->with('success','Profile saved.');}
 public function messages(Request $r){return view('messages',['links'=>$this->links()]+\App\Services\Conversations::page($r));}
 public function sendMessage(Request $r){$v=$r->validate(['recipient_id'=>'required|integer|exists:users,id','body'=>'required|string|max:1000','attachment'=>'nullable|file|mimes:jpg,jpeg,png|extensions:jpg,jpeg,png|max:5120']);$u=auth()->user();abort_if($v['recipient_id']==$u->id,422);$recipient=DB::table('users')->find($v['recipient_id']);abort_unless($recipient->active&&$recipient->approval_status==='approved',403);$roles=match($u->role){'buyer'=>['seller','admin'],'seller'=>['buyer','admin'],'admin'=>['buyer','seller'],'rider'=>['sorting_center'],'sorting_center'=>['rider','logistics_admin'],'logistics_admin'=>['sorting_center']};abort_unless(in_array($recipient->role,$roles,true),403);if($u->role==='rider')abort_unless($u->company_id==$recipient->id,403);if($u->role==='sorting_center'&&$recipient->role==='rider')abort_unless($recipient->company_id==$u->id,403);unset($v['attachment']);if($r->hasFile('attachment'))$v['attachment']=$r->file('attachment')->store('chat','local');DB::table('messages')->insert($v+['sender_id'=>$u->id,'created_at'=>now(),'updated_at'=>now()]);return $r->expectsJson()?response()->json(['message'=>'Sent.']):redirect('/messages?with='.$v['recipient_id'])->with('success','Message sent.');}
}
